    pub fn new(api: ApiClient) -> Self {
        Self { api }
    }

    /// Creates a new SQL warehouse.
    ///
    /// `POST /api/2.0/sql/warehouses`
    pub async fn create(
        &self,
        request: CreateWarehouseRequest,
    ) -> ::community_databricks_core::Result<WaitGetWarehouseRunning<CreateWarehouseResponse>> {
        let path = String::from("/api/2.0/sql/warehouses");
        let mut call = Call::new(Method::POST, path).workspace();
        call = call.json(&request)?;
        let response = self.api.send::<CreateWarehouseResponse>(call).await?;
        let param = response.id.clone().unwrap_or_default();
        Ok(WaitGetWarehouseRunning {
            api: Clone::clone(self),
            id: param,
            response,
            timeout: ::std::time::Duration::from_secs(1200),
            on_progress: None,
        })
    }

    /// Creates a new default warehouse override for a user. Users can create their
    /// own override. Admins can create overrides for any user.
